+  title: "Closed-Loop Pipeline: From Multi-User Interaction to Shared Skill Evolution",
+};
+
+function createSlide(pres, theme) {
+  const slide = pres.addSlide();
+  slide.background = { color: theme.bg };
+
+  const header = addTopBar(
+    slide,
+    theme,
+    tokens,
+    "SkillClaw architecture overview",
+    "Multi-user interaction → session collection → agentic evolution → skill synchronization"
+  );
+
+  // Left: figure_1 hero (architecture figure)
+  const leftX = header.x;
+  const leftY = header.contentY + 0.25;
+  const leftW = 6.15;
+  const leftH = 4.55;
+
+  slide.addShape("roundRect", {
+    x: leftX,
+    y: leftY,
+    w: leftW,
+    h: leftH,
+    fill: { color: theme.bg },
+    line: { color: theme.light, transparency: 25 },
+    rectRadius: 0.12,
+  });
+  slide.addImage({ path: resolveImg("figure_1.jpg"), x: leftX + 0.1, y: leftY + 0.1, w: leftW - 0.2, h: leftH - 0.2 });
+
+  // Right: 4-stage loop diagram (Evidence / Attribution / Evolution / Distribution)
+  const rightX = leftX + leftW + tokens.gap;
+  const rightY = leftY;
+  const rightW = header.w - leftW - tokens.gap;
+  const rightH = leftH;
+  addCard(slide, theme, tokens, rightX, rightY, rightW, rightH);
+
+  slide.addText("Four-stage closed loop", {
+    x: rightX + tokens.cardPad,
+    y: rightY + 0.2,
+    w: rightW - tokens.cardPad * 2,
+    h: 0.35,
+    fontFace: "Cambria",
+    fontSize: 18,
+    bold: true,
+    color: theme.primary,
+  });
+
+  const cx = rightX + rightW / 2;
+  const cy = rightY + 2.55;
+  const boxW = rightW - 0.6;
+  const boxH = 0.55;
+  const boxX = rightX + 0.3;
+  const stages = [
+    { label: "1) Evidence", y: cy - 1.55, fill: theme.secondary },
+    { label: "2) Attribution", y: cy - 0.55, fill: theme.accent },
+    { label: "3) Evolution", y: cy + 0.45, fill: theme.secondary },
+    { label: "4) Distribution", y: cy + 1.45, fill: theme.accent },
+  ];
+
+  for (const s of stages) {
+    slide.addShape("roundRect", {
+      x: boxX,
+      y: s.y,
+      w: boxW,
+      h: boxH,
+      fill: { color: s.fill, transparency: 18 },
+      line: { color: s.fill, transparency: 0 },
+      rectRadius: 0.12,
+    });
+    slide.addText(s.label, {
+      x: boxX + 0.15,
+      y: s.y + 0.12,
+      w: boxW - 0.3,
+      h: 0.32,
+      fontFace: "Calibri",
+      fontSize: 15,
+      color: theme.primary,
+    });
+  }
+
+  // Connectors (downward)
+  for (let i = 0; i < stages.length - 1; i++) {
+    slide.addShape("line", {
+      x: cx,
+      y: stages[i].y + boxH,
+      w: 0,
+      h: stages[i + 1].y - (stages[i].y + boxH),
+      line: { color: theme.primary, width: 2, beginArrowType: "none", endArrowType: "triangle" },
+    });
+  }
+
+  // Close the loop: arrow from Distribution back to Evidence (right edge)
+  const loopRightX = rightX + rightW - 0.25;
+  const topEdgeY = stages[0].y + boxH / 2;
+  const bottomEdgeY = stages[3].y + boxH / 2;
+  slide.addShape("line", {
+    x: loopRightX,
+    y: bottomEdgeY,
+    w: 0,
+    h: -(bottomEdgeY - topEdgeY),
+    line: { color: theme.primary, width: 2 },
+  });
+  slide.addShape("line", {
+    x: loopRightX,
+    y: topEdgeY,
+    w: -(boxW - 0.1),
+    h: 0,
+    line: { color: theme.primary, width: 2, beginArrowType: "none", endArrowType: "triangle" },
+  });
+
+  slide.addText(
+    "Evidence base is formed by grouping trajectories by referenced skill; verified updates are merged and synchronized back to all agents.",
+    {
+      x: rightX + tokens.cardPad,
+      y: rightY + 4.2,
+      w: rightW - tokens.cardPad * 2,
+      h: 0.6,
+      fontFace: "Calibri",
+      fontSize: 11,
+      color: theme.secondary,
+    }
+  );
+
+  addFooter(slide, theme, "Figure: SkillClaw architecture overview", 3);
+  return slide;
+}
+
+module.exports = { createSlide, slideConfig };
+
*** End Patch
